import urllib.request
import urllib.parse
import json
import re
import csv

# Available ingredients from our stock
available = {
    '鸡蛋': '2个',
    '土豆': '100g',
    '茄子': '200g',
    '蒜苗': '100g',
    '冬瓜': '100g',
    '瘦猪肉片': '150g',
    '五花肉': '100g',
    '牛奶': '30ml',
    '干辣椒': '50g'
}

def fetch_dir(path):
    encoded = urllib.parse.quote(path, safe=' /')
    url = f'https://api.github.com/repos/Anduin2017/HowToCook/contents/{encoded}'
    req = urllib.request.Request(url, headers={'User-Agent': 'Python'})
    with urllib.request.urlopen(req) as resp:
        items = json.loads(resp.read())
    md_files = []
    dirs = []
    for item in items:
        if item['type'] == 'file' and item['name'].endswith('.md'):
            md_files.append(item)
        elif item['type'] == 'dir':
            dirs.append(item)
    for d in dirs:
        md_files.extend(fetch_dir(d['path']))
    return md_files

def parse_ingredients(content):
    ingredients = {}
    lines = content.split('\n')
    for line in lines:
        line = line.strip()
        m = re.match(r'^[-\u2022\*]\s+(.+?)\s+(\d+\s*(?:个|g|kg|ml|l|片|颗|瓣|根|条|块|勺|大勺|小勺|汤匙|茶匙|滴|段|粒|头|只|枚|截|杯|碗|盘|碟|撮|份))', line)
        if m:
            name = m.group(1).strip()
            qty = m.group(2).strip()
            ingredients[name] = qty
        if '## 制作步骤' in line or '## 做法' in line or '## 步骤' in line or '### 制作步骤' in line:
            break
    return ingredients

def get_dish_name(content):
    for line in content.split('\n'):
        m = re.match(r'^#\s+(.+)', line.strip())
        if m:
            return m.group(1).strip()
    return None

print("Fetching recipe list...")
md_files = fetch_dir('dishes')
print(f"Found {len(md_files)} recipe files")

recipes = []
for i, f in enumerate(md_files):
    url = f['download_url']
    req = urllib.request.Request(url, headers={'User-Agent': 'Python'})
    try:
        with urllib.request.urlopen(req) as resp:
            content = resp.read().decode('utf-8')
        name = get_dish_name(content)
        ingredients = parse_ingredients(content)
        if name and ingredients:
            matched = 0
            matched_ingredients = []
            for ing in ingredients:
                if ing in available:
                    matched += 1
                    matched_ingredients.append(ing)
                else:
                    for av in available:
                        if av in ing or ing in av:
                            matched += 1
                            matched_ingredients.append(ing)
                            break
            total_ingredients = len(ingredients)
            match_ratio = matched / total_ingredients if total_ingredients > 0 else 0
            recipes.append({
                'name': name,
                'ingredients': ingredients,
                'matched': matched,
                'total': total_ingredients,
                'ratio': match_ratio,
                'matched_list': matched_ingredients
            })
    except Exception as e:
        print(f"Error parsing {f['name']}: {e}")
    if (i+1) % 50 == 0:
        print(f"  Processed {i+1}/{len(md_files)}")

print(f"\nParsed {len(recipes)} recipes")

candidates = []
for r in recipes:
    if r['ratio'] >= 0.5 and r['matched'] >= 2:
        candidates.append(r)

candidates.sort(key=lambda x: (-x['matched'], -x['ratio']))

print(f"\nCandidates with >= 50% coverage and >= 2 matches: {len(candidates)}")
for c in candidates[:20]:
    print(f"  {c['name']}: {c['matched']}/{c['total']} ({c['ratio']:.0%}) - matched: {c['matched_list']}")

selected = []
used_keywords = set()
for r in candidates:
    if len(selected) >= 3:
        break
    keywords = [kw for kw in r['matched_list'] if kw not in used_keywords]
    if keywords or len(selected) < 3:
        selected.append(r)
        used_keywords.update(r['matched_list'])

print(f"\nSelected {len(selected)} dishes:")
for s in selected:
    print(f"  {s['name']}")
    for ing, qty in s['ingredients'].items():
        status = 'OK' if ing in available else 'MISSING'
        print(f"    [{status}] {ing}: {qty}")

cuisine = {"recommended_dishes": []}
for s in selected:
    dish = {"name": s['name'], "ingredients": {}}
    for ing, qty in s['ingredients'].items():
        dish["ingredients"][ing] = qty
    cuisine["recommended_dishes"].append(dish)

with open('/app/cuisine.json', 'w', encoding='utf-8') as f:
    json.dump(cuisine, f, ensure_ascii=False, indent=4)
print("\nSaved cuisine.json")

shopping = []
for s in selected:
    for ing, qty in s['ingredients'].items():
        if ing not in available:
            shopping.append({'Name': ing, 'Quantity': qty})
        elif ing in available and qty != available[ing]:
            # We have less than needed - list what we need more
            shopping.append({'Name': ing, 'Quantity': qty})

with open('/app/shopping.csv', 'w', encoding='utf-8', newline='') as f:
    writer = csv.DictWriter(f, fieldnames=['Name', 'Quantity'])
    writer.writeheader()
    writer.writerows(shopping)
print(f"Saved shopping.csv with {len(shopping)} items")
