import os
import re
import json
import csv
from pathlib import Path

available = {
    '鸡蛋': '2个',
    '土豆': '100g',
    '茄子': '200g',
    '蒜苗': '100g',
    '冬瓜': '100g',
    '瘦猪肉片': '150g',
    '五花肉': '100g',
    '牛奶': '30ml',
    '干辣椒': '50g'
}

def parse_recipes(repo_path):
    dishes_dir = os.path.join(repo_path, 'dishes')
    recipes = []
    for root, dirs, files in os.walk(dishes_dir):
        for fname in files:
            if not fname.endswith('.md'):
                continue
            fpath = os.path.join(root, fname)
            try:
                with open(fpath, 'r', encoding='utf-8') as f:
                    content = f.read()
            except:
                continue

            # Get dish name from first # header
            name = None
            for line in content.split('\n'):
                m = re.match(r'^#\s+(.+)', line.strip())
                if m:
                    name = m.group(1).strip()
                    break
            if not name:
                continue

            # Try to find ingredient section
            ingredients = {}

            # Strategy 1: Look for "## 计算" section and parse lines after it
            calc_match = re.search(r'## 计算\n(.*?)(?:## |$)', content, re.DOTALL)
            if calc_match:
                calc_section = calc_match.group(1)

                # Strategy 1a: Parse "- ingredient quantity" or "* ingredient quantity" style
                for line in calc_section.split('\n'):
                    line = line.strip()
                    if not line:
                        continue
                    # Skip metadata lines
                    if line.startswith('#') or line.startswith('---') or line.startswith('**'):
                        continue
                    if '=' in line and not line.strip().startswith('-') and not line.strip().startswith('*'):
                        continue

                    # Pattern: - ingredient_name quantity (e.g., "- 鸡蛋 2个")
                    # Or:   - ingredient_name = quantity
                    # Or:   * ingredient quantity
                    m = re.match(r'^[-*]\s+(.+?)\s*=?\s*(\d+\s*[一-鿿\u00b7.gkgmla-zA-Z]+)\b', line)
                    if not m:
                        m = re.match(r'^[-*]\s+(.+?)\s*=\s*(\d+\s*[一-鿿\u00b7.gkgmla-zA-Z]+)\b', line)
                    if m:
                        ing_name = m.group(1).strip()
                        ing_qty = m.group(2).strip()
                        # Remove trailing unit suffixes for cleaner name
                        if '(' in ing_name:
                            ing_name = ing_name[:ing_name.index('(')].strip()
                        # Skip if it looks like a note or instruction
                        if len(ing_name) < 1:
                            continue
                        if ing_name in ('必须配料', '进阶配料', '可选配料', '主料', '调料', '香料包', '丸子部分', '酱汁部分'):
                            continue
                        # Skip measurement conversion lines
                        if '汤匙' in ing_name or '茶匙' in ing_name and '=' in line:
                            if re.match(r'^-\s+\d+', line):
                                continue
                        ingredients[ing_name] = ing_qty

                # Strategy 1b: Parse table format under 计算
                # |原料|数量|单位|
                table_pattern = re.compile(r'\|([^|]+)\|([^|]+)\|[^|]*\|')
                for line in calc_section.split('\n'):
                    table_match = table_pattern.match(line.strip())
                    if table_match:
                        tname = table_match.group(1).strip()
                        tqty = table_match.group(2).strip()
                        if tname in ('原料', '数量', '单位'):
                            continue
                        # Only add if it looks like an actual ingredient
                        if tname and tqty:
                            ingredients[tname] = tqty

            # Strategy 2: If no 计算 section, try the main ingredient list under "## 必备原料和工具"
            if not ingredients:
                ing_section = re.search(r'## 必备原料和工具\n(.*?)(?:## |$)', content, re.DOTALL)
                if ing_section:
                    for line in ing_section.group(1).split('\n'):
                        line = line.strip()
                        if line.startswith('- '):
                            ing = line[2:].strip()
                            # Remove note in parentheses
                            if '(' in ing:
                                ing = ing[:ing.index('(')].strip()
                            if ing and len(ing) > 1 and ing not in ('可选原料',):
                                ingredients[ing] = ''

            if not ingredients:
                continue

            recipes.append({'name': name, 'ingredients': ingredients})

    return recipes

def match_score(name, ingredients, available):
    matched = []
    for ing in ingredients:
        # Direct match
        if ing in available:
            matched.append(ing)
        else:
            # Check if available ingredient is in the recipe ingredient or vice versa
            # e.g., "鸡蛋" matches "鸡蛋 2个" or "鸡蛋"
            for av in available:
                if av in ing or ing in av:
                    matched.append(ing)
                    break
            # Also try removing common suffixes
            if not any(m in available for m in matched[-1:] if matched):
                # strip numbers/units from name
                clean = re.sub(r'[\s0-9一-鿿\u00b7gkgmlA-Z/.（）\-=]+$]', '', ing).strip()
                if clean in available:
                    matched.append(ing)
    ratio = len(matched) / len(ingredients) if ingredients else 0
    return len(matched), ratio, matched

print("Loading recipes...")
recipes = parse_recipes('/tmp/HowToCook')
print(f"Loaded {len(recipes)} recipes")

# Score and filter
scores = []
for r in recipes:
    matched_count, ratio, matched_list = match_score(r['name'], r['ingredients'], available)
    # Need at least half of ingredient types from our stock, and at least 2 matches
    if ratio >= 0.5 and matched_count >= 2:
        scores.append({
            'name': r['name'],
            'ingredients': r['ingredients'],
            'matched_count': matched_count,
            'total': len(r['ingredients']),
            'ratio': ratio,
            'matched_list': matched_list
        })

scores.sort(key=lambda x: (-x['matched_count'], -x['ratio']))

print(f"\nCandidates (>=50% coverage, >=2 matches): {len(scores)}")
for c in scores[:30]:
    print(f"  {c['name']}: {c['matched_count']}/{c['total']} ({c['ratio']:.0%}) - matched: {c['matched_list']}")

# Select 3 diverse dishes
selected = []
for s in scores:
    if len(selected) >= 3:
        break
    selected.append(s)

print(f"\nSelected {len(selected)} dishes:")
for s in selected:
    print(f"  {s['name']} ({s['matched_count']}/{s['total']})")
    for ing, qty in s['ingredients'].items():
        has = 'OK' if ing in available else 'MISSING'
        print(f"    [{has}] {ing}: {qty}")

# Save cuisine.json
cuisine = {"recommended_dishes": []}
for s in selected:
    dish = {"name": s['name'], "ingredients": {}}
    for ing, qty in s['ingredients'].items():
        dish["ingredients"][ing] = qty
    cuisine["recommended_dishes"].append(dish)

with open('/app/cuisine.json', 'w', encoding='utf-8') as f:
    json.dump(cuisine, f, ensure_ascii=False, indent=4)
print("\nSaved cuisine.json")

# Shopping list: ingredients not in stock, or we have less than needed
shopping = []
for s in selected:
    for ing, qty in s['ingredients'].items():
        if ing not in available:
            shopping.append({'Name': ing, 'Quantity': qty})
        elif available[ing] != qty and qty:
            # We have some but need more - list what's needed
            shopping.append({'Name': ing, 'Quantity': qty})

with open('/app/shopping.csv', 'w', encoding='utf-8', newline='') as f:
    writer = csv.DictWriter(f, fieldnames=['Name', 'Quantity'])
    writer.writeheader()
    writer.writerows(shopping)
print(f"Saved shopping.csv with {len(shopping)} items")
if shopping:
    for item in shopping:
        print(f"  {item['Name']}: {item['Quantity']}")
