import os, re, json, csv

# Our available ingredients with quantities
available_names = ['鸡蛋', '土豆', '茄子', '蒜苗', '冬瓜', '瘦猪肉片', '五花肉', '牛奶', '干辣椒']
available = {
    '鸡蛋': '2个', '土豆': '100g', '茄子': '200g', '蒜苗': '100g',
    '冬瓜': '100g', '瘦猪肉片': '150g', '五花肉': '100g', '牛奶': '30ml', '干辣椒': '50g'
}

# Mapping: normalize common recipe names to our available ingredient names
ING_MAP = {
    '鸡蛋': '鸡蛋', '鸡蛋 ': '鸡蛋',
    '纯瘦肉': '瘦猪肉片', '瘦肉': '瘦猪肉片', '猪肉': '瘦猪肉片',
    '猪肉末': '瘦猪肉片', '肉末': '瘦猪肉片', '瘦猪肉': '瘦猪肉片',
    '五花肉': '五花肉', '带皮五花肉': '五花肉', '五花肉条': '五花肉', '肥肉': '五花肉',
    '茄子': '茄子', '青茄子': '茄子',
    '蒜苗': '蒜苗', '蒜苗 ': '蒜苗',
    '冬瓜': '冬瓜',
    '干辣椒': '干辣椒', '干辣椒（或者二荆条）': '干辣椒',
    '牛奶': '牛奶', '全脂牛奶/奶油': '牛奶',
}

def clean_name(name):
    """Clean an ingredient name from recipe format."""
    # Remove emojis
    name = re.sub(r'[\U0001F600-\U0001F9FF]', '', name).strip()
    # Remove notes in parentheses
    for ch in ['(', ')', '（', ')']:
        if ch in name:
            name = name[:name.index(ch)].strip()
    # Remove trailing non-chars
    name = re.sub(r'[\s=]+.*$', '', name).strip()
    return name

def normalize(name):
    """Normalize ingredient name to our standard names."""
    name = clean_name(name)
    if not name:
        return None
    # Direct match
    if name in available_names:
        return name
    if name in ING_MAP:
        return ING_MAP[name]
    # Try partial matching
    for av in available_names:
        if av in name or name in av:
            return av
    # Map common synonyms
    synonyms = {
        '青茄子': '茄子', '纯瘦肉': '瘦猪肉片', '瘦肉': '瘦猪肉片',
        '猪肉': '瘦猪肉片', '猪肉末': '瘦猪肉片', '肉末': '瘦猪肉片',
        '五花肉': '五花肉', '带皮五花肉': '五花肉',
    }
    if name in synonyms:
        return synonyms[name]
    return None

def parse_calculations(section):
    """Parse ingredient list from 计算 section text."""
    ingredients = {}
    for line in section.split('\n'):
        line = line.strip()
        if not line or line.startswith('#') or line.startswith('*') and line.startswith('**'):
            continue
        # Skip pure notes, empty lines, structural elements
        if line.startswith('- ') or line.startswith('* '):
            raw = line.lstrip('-*').strip()
        elif '=' in line and (line.startswith('- ') or line.startswith('* ')):
            raw = line.lstrip('-*').strip()
        else:
            continue
        # Try to extract: name and quantity
        # Patterns: "- 鸡蛋 2个", "- 鸡蛋 1 个", "- 土豆 200g"
        m = re.match(r'(.+?)\s+(\d+\s*[\u4e00-\u9fff\u00b7.gkgmla-zA-Z/]+)', raw)
        if not m:
            m = re.match(r'(.+?)\s*=\s*(.+)', raw)
        if m:
            name = clean_name(m.group(1).strip())
            qty = m.group(2).strip()
            if not name or len(name) < 1:
                continue
            # Skip if it looks like a note/category
            skip = ['每份', '总量', '主料', '调料', '香料包', '丸', '酱', '操作',
                    '必须配料', '进阶配料', '可选配料', '用量', '每份：']
            if any(s in name for s in skip):
                continue
            ingredients[name] = qty
    return ingredients

def parse_recipe(fpath):
    """Parse a recipe markdown file and return (name, ingredients_dict)."""
    try:
        with open(fpath, 'r', encoding='utf-8') as f:
            content = f.read()
    except:
        return None

    # Get dish name
    name = None
    for line in content.split('\n'):
        m = re.match(r'^#\s+(.+)', line.strip())
        if m:
            name = m.group(1).strip()
            # Remove .做法 suffix
            name = name.replace('.做法', '').strip()
            break
    if not name:
        return None

    ingredients = {}

    # Try 计算 section
    calc_match = re.search(r'## 计算\n(.*?)(?:^## |\Z)', content, re.DOTALL | re.MULTILINE)
    if calc_match:
        ingredients = parse_calculations(calc_match.group(1))

    # Also try table format
    if not ingredients:
        table_matches = re.findall(r'\|([^|]+)\s*\|\s*([^|]+)\s*\|\s*([^|]*)\|', calc_match.group(1))
        for row in table_matches:
            tn, tq = row[0].strip(), row[1].strip()
            if tn not in ('原料', '数量', '单位') and tn and tq:
                ingredients[tn] = tq

    if not ingredients:
        # Try 必备原料 section
        ing_match = re.search(r'## 必备原料和工具\n(.*?)(?:^## |\Z)', content, re.DOTALL | re.MULTILINE)
        if ing_match:
            for line in ing_match.group(1).split('\n'):
                line = line.strip()
                if line.startswith('- ') or line.startswith('* '):
                    raw = line.lstrip('-* ').strip()
                    if '(' in raw:
                        raw = raw[:raw.index('(')].strip()
                    if raw and len(raw) > 1:
                        ingredients[raw] = ''

    if not ingredients:
        return None

    # Normalize names
    norm = {}
    for k, v in ingredients.items():
        n = normalize(k)
        if n:
            norm[n] = v

    return {'name': name, 'ingredients': norm}

# Parse all recipes
recipes = []
for root, dirs, files in os.walk('/tmp/HowToCook/dishes'):
    for fname in files:
        if not fname.endswith('.md'):
            continue
        result = parse_recipe(os.path.join(root, fname))
        if result:
            recipes.append(result)

print(f"Parsed {len(recipes)} recipes")

# Score each recipe
candidates = []
for r in recipes:
    matched = [n for n in r['ingredients'] if n in available_names]
    total = len(r['ingredients'])
    ratio = len(matched) / total if total > 0 else 0
    if ratio >= 0.5 and len(matched) >= 2:
        candidates.append({
            'name': r['name'],
            'ingredients': r['ingredients'],
            'matched': matched,
            'total': total,
            'ratio': ratio
        })

candidates.sort(key=lambda x: (-len(x['matched']), -x['ratio']))

print(f"\nCandidates (>=50% coverage, >=2 matches): {len(candidates)}")
for i, c in enumerate(candidates[:30]):
    print(f"  {i+1}. {c['name']}: {len(c['matched'])}/{c['total']} ({c['ratio']:.0%}) - {c['matched']}")

# Select top 3 with diversity
selected = []
for c in candidates:
    if len(selected) >= 3:
        break
    selected.append(c)

print(f"\n=== Selected {len(selected)} dishes ===")
for s in selected:
    print(f"\n{s['name']} ({len(s['matched'])}/{s['total']} matched)")
    for ing, qty in s['ingredients'].items():
        status = 'IN_STOCK' if ing in available_names else 'MISSING'
        print(f"  [{status}] {ing}: {qty}")

# Save cuisine.json
cuisine = {"recommended_dishes": []}
for s in selected:
    dish = {"name": s['name'], "ingredients": {}}
    for ing, qty in s['ingredients'].items():
        dish["ingredients"][ing] = qty
    cuisine["recommended_dishes"].append(dish)

with open('/app/cuisine.json', 'w', encoding='utf-8') as f:
    json.dump(cuisine, f, ensure_ascii=False, indent=4)
print("\nSaved cuisine.json")

# Shopping list
shopping = []
for s in selected:
    for ing, qty in s['ingredients'].items():
        if ing not in available:
            shopping.append({'Name': ing, 'Quantity': qty})

with open('/app/shopping.csv', 'w', encoding='utf-8', newline='') as f:
    writer = csv.DictWriter(f, fieldnames=['Name', 'Quantity'])
    writer.writeheader()
    writer.writerows(shopping)
print(f"Saved shopping.csv with {len(shopping)} items")
for item in shopping:
    print(f"  {item['Name']}: {item['Quantity']}")
