    name = re.sub(r'^\d+\s*', '', name).strip()
    ingredients = parse_all_ingredients(
        re.search(r'## 计算\n(.*?)(?:^## |\Z)', content, re.DOTALL | re.MULTILINE).group(1)
        if re.search(r'## 计算', content, re.DOTALL | re.MULTILINE) else ''
    )
    if not ingredients:
        ing_match = re.search(r'## 必备原料和工具\n(.*?)(?:^## |\Z)', content, re.DOTALL | re.MULTILINE)
        if ing_match:
            for line in ing_match.group(1).split('\n'):
                line = line.strip()
                if line.startswith('- ') or line.startswith('* '):
                    raw = line.lstrip('-* ').strip()
                    for sep in ['(', '（']:
                        if sep in raw: raw = raw[:raw.index(sep)].strip()
                    ingredients.append((clean_raw(raw), ''))
    if not ingredients:
        return None
    return {'name': name, 'all_ingredients': ingredients}

recipes = []
for root, dirs, files in os.walk('/tmp/HowToCook/dishes'):
    for fname in sorted(files):
        if not fname.endswith('.md'): continue
        result = parse_recipe(os.path.join(root, fname))
        if result: recipes.append(result)

candidates = []
for r in recipes:
    norm_dict = {}
    for orig, qty in r['all_ingredients']:
        norm = normalize_ingredient(orig)
        if norm and norm in available_names:
            norm_dict[norm] = qty
    matched = list(norm_dict.keys())
    total = len(r['all_ingredients'])
    ratio = len(matched) / total if total > 0 else 0
    if len(matched) >= 2:
        candidates.append({
            'name': r['name'],
            'ingredients': norm_dict,
            'all_ings': r['all_ingredients'],
            'matched': matched,
            'total': total,
            'ratio': ratio
        })

candidates.sort(key=lambda x: (-len(x['matched']), -x['ratio'], x['name']))

# Select 3 diverse dishes
selected_names = ['炒滑蛋', '地三鲜', '瘦肉土豆片']
selected = [c for c in candidates if c['name'] in selected_names]

print("=== Final Selection ===")
for s in selected:
    print(f"\n{s['name']} ({len(s['matched'])}/{s['total']} = {s['ratio']:.0%})")
    for orig, qty in s['all_ings']:
        norm = normalize_ingredient(orig)
        status = 'STOCK' if (norm and norm in available_names) else 'BUY'
        print(f"  [{status}] {orig}: {qty}")

# Save cuisine.json
cuisine = {"recommended_dishes": []}
for s in selected:
    dish = {"name": s['name'], "ingredients": {}}
    ing_dict = {}
    for orig, qty in s['all_ings']:
        key = normalize_ingredient(orig) if normalize_ingredient(orig) else orig
        if key not in ing_dict:
            ing_dict[key] = qty
    for k, v in ing_dict.items():
        dish["ingredients"][k] = v
    cuisine["recommended_dishes"].append(dish)

with open('/app/cuisine.json', 'w', encoding='utf-8') as f:
    json.dump(cuisine, f, ensure_ascii=False, indent=4)
print("\nSaved cuisine.json")

# Shopping list
shopping = []
for s in selected:
    for orig, qty in s['all_ings']:
        norm = normalize_ingredient(orig)
        if not norm or norm not in available_names:
            name = orig
            q = qty.strip() if qty else ''
            if q:
                shopping.append({'Name': name, 'Quantity': q})

with open('/app/shopping.csv', 'w', encoding='utf-8', newline='') as f:
    writer = csv.DictWriter(f, fieldnames=['Name', 'Quantity'])
    writer.writeheader()
    writer.writerows(shopping)
print(f"Saved shopping.csv with {len(shopping)} items")
for item in shopping:
    print(f"  {item['Name']}: {item['Quantity']}")
PYEOF
